learn=[('Use allow entries as pre-approval', 'allowedTools adds allow rules; it is not a complete inventory or a universal whitelist. The default experiment leaves Write available and sends that unlisted call to a denying callback. Reads inside the working directory can also be safe built-in approvals.'), ('Distinguish removal from runtime denial', 'A bare Write deny removes that definition. A scoped Bash(rm *) deny keeps Bash available and rejects matching calls as written. The live shell experiment uses one disposable fixture and an independent exact-operation guard.'), ('Match MCP globs correctly', 'An allow glob needs a literal server prefix, such as mcp__classroom__read_*. The live call on that server succeeds while the archive server call reaches the callback and is denied. The wildcard experiment verifies denied MCP execution while Read succeeds. In this pinned runtime MCP names remain in the reported snapshot, so inspect actual denial feedback.'), ('Protect writes using Edit path rules', 'The live Edit(./protected/**) deny protects a directory even though the model requests Write. A separate Write to result.txt succeeds. Reference notes distinguish relative, single-slash source-anchored and double-slash absolute patterns; Write(path) is not an equivalent scoped write rule.'), ('Load declarative project rules', 'The project experiment writes an actual .claude/settings.json in a fresh classroom directory and enables settingSources project. Its allow permits Read, deny protects a mock .env read and ask sends Write to the programmed callback.'), ('Compare dontAsk with bypass', 'The reviewer pre-approves Read/Glob/Grep and uses dontAsk, so its attempted Write is denied without a callback. With bypass and only Read in allowedTools, an unlisted Write executes. Verify actual native results and host file checks.')]
env='ANTHROPIC_API_KEY=your_api_key\nCLAUDE_MODEL=claude-sonnet-4-6\nPORT=3128\n# Windows if needed: CLAUDE_CODE_GIT_BASH_PATH=C:/Program Files/Git/bin/bash.exe\n'
runsteps=[('Prerequisites', 'Install Node.js 24 or later, have API credit and model access, and install Git for Windows if the SDK needs Git Bash. Python is needed only to regenerate the student pages.', 'node --version\nnpm --version'), ('Install and create your .env file', 'From presentations enter this app, install locked dependencies and preserve an existing .env. Enter your own model key privately. The mock .env used in one exercise is generated separately in a disposable directory.', 'cd .\\agent-sdk\\lesson28-allow-deny-rules\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env'), ('Start the application', 'Keep the terminal open and use the startup URL. The app creates the local MCP servers and temporary fixtures. No GitHub token or Managed Agents resource IDs are needed.', 'npm start\n# http://127.0.0.1:3128'), ('Compare the four rule forms', 'Run allow fallback, bare deny, scoped deny and MCP wildcard deny. Check whether a tool is absent from the reported inventory or actually attempted and rejected.', 'npm run sample:env -- allow-fallback\nnpm run sample:env -- bare-deny\nnpm run sample:env -- scoped-deny\nnpm run sample:env -- wildcard-deny'), ('Compare MCP globs, paths and project settings', 'Run the remaining rule experiments. Inspect the literal-server glob, protected Write denial and actual project allow/deny/ask behavior. The callback allows only the fixed classroom output in project mode.', 'npm run sample:env -- mcp-glob\nnpm run sample:env -- path-deny\nnpm run sample:env -- project-settings'), ('Compare reviewer dontAsk with bypass', 'Both modes keep Write available. The reviewer denies it without a callback; bypass permits the unlisted write. Compare actual outputs instead of treating allowedTools as a universal restriction.', 'npm run sample:env -- reviewer-dontAsk\nnpm run sample:env -- bypass-unlisted\nnpm test')]
specs=[('Validate the fixed rule experiment', 'src/rules.ts', 'export function validateConfig', 'Only listed modes and three prediction outcomes are accepted. The browser cannot supply arbitrary permission rules or tool commands.', 0, 1, 7), ('Create disposable fixtures and settings', 'src/workspace.ts', 'if (project) {', 'Project mode writes actual declarative rules into .claude/settings.json in a fresh working directory. The separate mock .env contains only an explicit classroom value.', 1, 4, 7), ('Pass allow and deny options', 'src/agent.ts', 'allowedTools: s.allowed,', 'Allow entries pre-approve matching calls. A bare deny removes the tool definition; a scoped deny leaves it available for a matching runtime rejection.', 1, 2, 5), ('Enable the project setting source', 'src/agent.ts', 'settingSources: s.project', 'The project source must be enabled for the generated settings file to contribute allow, deny and ask rules. Other experiments use an empty settings-source list.', 1, 2, 4), ('Protect writes with an Edit path rule', 'src/rules.ts', '"path-deny": {', 'The live relative Edit path rule governs a model Write to protected/report.txt. An independent Write to result.txt remains eligible for approval.', 1, 2, 8), ('Register local MCP servers', 'src/classroom-tools.ts', 'return Object.fromEntries', 'Two literal server names expose real read_lesson handlers. The classroom allow glob matches one server; the archive call remains a separate permission decision.', 1, 3, 8), ('Pass bounded operations without approving', 'src/agent.ts', 'const pass = hostAllows', 'The host guard narrows inputs to this exercise, then returns no permission decision for valid operations. This lets SDK allow and deny rules produce the observed outcome.', 2, 1, 8), ('Resolve remaining calls in the callback', 'src/agent.ts', 'canUseTool: async', 'Only the project-settings Write is allowed here. Other unresolved requests are denied. Compare a callback rejection with an absent tool or an automatic mode approval.', 2, 3, 8), ('Start the actual SDK query', 'src/agent.ts', 'const run = query', 'Each query uses its fresh directory and fixed tasks. Tools that were removed cannot be requested; the model must not fabricate an unavailable call.', 1, 2, 5), ('Observe the actual tool inventory', 'src/agent.ts', 'inventory = message.tools;', 'Preserve reported initialization names and compare them with actual attempts, native denials and MCP handler execution. Bare Write removal and MCP wildcard behavior differ in the pinned runtime.', 2, 1, 6), ('Preserve native rejection evidence', 'src/agent.ts', 'if (block.is_error)', 'A denied operation yields native feedback. A successful final model explanation does not establish that every requested operation executed.', 2, 0, 7), ('Verify files and protected fixtures', 'src/workspace.ts', 'fileCreated: fileContents', 'Host checks compare actual output content, the removal fixture, protected-write absence and the mock environment fixture. Evidence is collected before cleanup.', 4, 1, 6), ('Render the student prediction feedback', 'src/client.ts', '$("verdict").textContent =', 'Compare the student prediction with observed execute, block or mixed outcomes. Keep configuration reference labels separate from live event evidence.', 1, 0, 3)]
document('/','Allow and deny. <em>Match the rule.</em>','Compare rule forms, MCP globs, file paths and project settings with actual SDK evidence.','<div class="flow"><div><b>01 · Declare</b><p>Choose a rule experiment</p></div><span>→</span><div><b>02 · Match</b><p>Observe real attempts and decisions</p></div><span>→</span><div><b>03 · Verify</b><p>Inventory, handlers and files</p></div></div><section class="panel" id="controls"><h2>Explore allow and deny rules</h2><p id="configuration" class="meta">Checking local server…</p><label for="mode">Rule experiment</label><select id="mode"><option value="allow-fallback">Allow entry · unlisted Write reaches callback</option><option value="bare-deny">Bare deny · Write removed from definitions</option><option value="scoped-deny">Scoped deny · Bash remains but rm is blocked</option><option value="wildcard-deny">Wildcard deny · verify actual MCP denials</option><option value="mcp-glob">MCP allow glob · literal server prefix</option><option value="path-deny">Edit path rule · protected Write denied</option><option value="project-settings">Project settings · allow, deny and ask</option><option value="reviewer-dontAsk">Reviewer · pre-approved reads plus dontAsk</option><option value="bypass-unlisted">Bypass · unlisted Write executes</option></select><label for="prediction">Predict the attempted tool outcomes</label><select id="prediction"><option value="mixed">Mixed · some execute and some are denied</option><option value="execute">Execute · available requested operations succeed</option><option value="block">Block · no requested operation completes</option></select><button id="run" class="primary" disabled>Run rule experiment →</button><p class="meta">Fresh disposable files and local MCP tools keep these live exercises bounded. Mixed means at least one successful completion and native rejection. Removed tools cannot be attempted. Callback approvals are programmed host policy.</p></section><div class="workspace"><section class="panel" id="outcome"><h2 id="status" aria-live="polite">Ready</h2><p>Latest SDK-reported cost: <strong id="cost">—</strong></p><p class="meta">Session: <span id="session">—</span></p><div id="answer" class="markdown-body"></div><p id="notice" class="note"></p></section><section class="panel" id="option-panel"><h2>Options actually passed</h2><pre class="json-view"><code id="options" class="language-json">{}</code></pre><p>Compare the explicit tool inventory, allow and deny rules, setting sources and mode. Reference expectations are separate from observed evidence.</p></section></div><section class="step" id="pipeline-panel"><h2>Rule forms · reference</h2><p>These cards describe documented semantics. The events below contain actual observations. Global * and absolute-path examples are reference topics; the live path experiment uses a relative anchor.</p><div class="grid"><article class="card"><h3>Allow entry</h3><p>Pre-approves matching calls. Unlisted tools can still exist and reach the mode or callback.</p></article><article class="card"><h3>Bare deny</h3><p>Removes a matching tool definition before the model can request it.</p></article><article class="card"><h3>Scoped deny</h3><p>Keeps the tool and rejects matching commands or paths at runtime.</p></article><article class="card"><h3>Wildcard deny</h3><p>The mcp__* form denies matching MCP calls; this runtime still reports their names. A global * deny removes every tool definition.</p></article><article class="card"><h3>MCP allow glob</h3><p>Use a literal server prefix, such as mcp__classroom__read_*. A glob in the server segment is invalid.</p></article><article class="card"><h3>Path rule</h3><p>Edit(./protected/**) covers Write too. Use Edit(path), not Write(path), for scoped file-write rules.</p></article></div></section><section class="step" id="configuration-panel"><h2>Actual options or project settings</h2><label for="configuration-file">Configuration projection</label><select id="configuration-file"></select><pre class="json-view"><code id="configuration-content" class="language-json">{}</code></pre><p>Project mode shows the actual generated .claude/settings.json. The protected .env is a separate mock classroom fixture, not the app’s private credential file.</p></section><section class="step" id="discovery-panel"><h2>Actual reported tool-name snapshot</h2><pre class="json-view"><code id="discovery" class="language-json">{}</code></pre><p>Bare Write is removed in its experiment. This runtime still reports MCP names under wildcard deny and returns native permission denials. A reported name does not establish approval.</p></section><section class="step" id="trace-panel"><h2>Actual hooks and callback invocations</h2><pre class="json-view"><code id="trace" class="language-json">{}</code></pre><p>The host guard passes only fixed classroom operations without approving them. SDK rules then determine whether the callback is reached.</p></section><section class="step" id="native-panel"><h2>Actual native tool results</h2><pre class="json-view"><code id="native" class="language-json">{}</code></pre><p>Inspect successful data and denial feedback separately. The model can finish successfully after reporting a denied operation.</p></section><section class="step" id="warning-panel"><h2>Actual SDK warning codes</h2><pre class="json-view"><code id="warnings" class="language-json">{}</code></pre><p>Warnings are partial configuration diagnostics. Use actual tool events and independent checks to assess the result.</p></section><section class="step" id="evidence-panel"><h2>Independent inventory, handler and file evidence</h2><pre class="json-view"><code id="evidence" class="language-json">{}</code></pre><p>Check reported tool names, MCP handler calls, callback count, output contents and protected fixtures. No internal rule-comparison events are invented.</p></section><section class="step" id="comparison-panel"><h2>Compare predictions with observed outcomes</h2><p id="verdict">Predict execute, block or mixed before running.</p><div class="table"><table><thead><tr><th>Mode</th><th>Reference rule</th><th>Prediction</th><th>Observed</th><th>Callbacks</th><th>Completed</th><th>Fixture</th></tr></thead><tbody id="history"></tbody></table></div><button id="download">Download redacted observations</button></section><section class="step" id="event-panel"><h2>Actual SDK messages</h2><ul id="events"></ul></section>','<script type="module" src="/client.js"></script>')
document('/learn.html','What you <em>will learn.</em>','Understand declared rules and verify inventory, callback and file outcomes.',cards(learn))
body=''
for i,(title,explanation,code) in enumerate(runsteps,1):body+=f'<section class="step" id="run-step-{i}"><span class="number">{i:02}</span><h2>{title}</h2><p>{explanation}</p>'+snippet(code,'powershell')+'</section>'
body+='<section class="step"><h2>Your .env configuration</h2>'+snippet(env,'dotenv')+'<p>Only your model key is required. Keep it local and restart after edits. Existing shell variables take precedence.</p></section><section class="note"><h3>Troubleshooting</h3><p>Use Node 24+, API credit and a supported model. Configure Git Bash on Windows if requested. If the port is occupied, use the printed existing-app URL or change PORT. Distinguish removed tools from denied attempts. For project rules, check settingSources includes project. Scoped write rules use Edit(path), not Write(path). Read native feedback and host file evidence before concluding that a rule matched.</p></section>'
document('/run.html','Configure and <em>run the app.</em>','Install the SDK, configure your key and run the classroom comparisons.',body)
steps=[];arrows=[];lanes=['Student UI','TypeScript host','SDK rules','Host / MCP','Lab files']
for n,(title,source,anchor,explanation,a,b,count) in enumerate(specs,1):
 text=(APP/source).read_text(encoding='utf-8');lines=text.splitlines();idx=next(i for i,l in enumerate(lines) if anchor in l)
 code='\n'.join(lines[idx:idx+count]).strip()
 steps.append(dict(number=n,title=title,source=source,code=code,language='typescript',explanation=explanation,firstLine=idx+1,lastLine=idx+count,anchors=[lines[idx].strip()],sourceSHA256=hashlib.sha256(text.encode()).hexdigest(),narration=f'Step {n}. {explanation} This source excerpt shows the corresponding application statement.'))
 arrows.append([a,b,f'{n}. {title}'])
(APP/'scripts/architecture-data.json').write_text(json.dumps(dict(lanes=lanes,arrows=arrows,steps=steps),indent=2),encoding='utf-8')
